const cleanText = (value, maxLength) => {
  if (typeof value !== 'string') return '';
  const trimmed = value.trim().replace(/\s+/g, ' ');
  return trimmed.slice(0, maxLength);
};

const cleanEmail = (value) => {
  if (typeof value !== 'string') return '';
  const trimmed = value.trim();
  if (trimmed === '') return '';
  if (trimmed.length > 320 || /\s/.test(trimmed) || !trimmed.includes('@')) return null;
  return trimmed;
};

/***
 * MARK: parseResultsArtifact
 * @description Leniently parses a raw results artifact into a fully
 *   populated, render-safe shape. Never throws and never crashes the view:
 *   missing sections get safe defaults, malformed entries are skipped with
 *   a warning, unknown criterion/outcome ids are ignored with a warning,
 *   and criteria the artifact omits render as `unknown` (an honest gap, not
 *   a silent pass). Returns `{ artifact, warnings }`.
 * @example parseResultsArtifact(null).artifact.wcag22aaa.length => 28
 * @example parseResultsArtifact(FALLBACK_ARTIFACT).warnings => []
 ***/
export const parseResultsArtifact = (raw) => {
  const warnings = [];
  const source = raw !== null && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};
  if (raw === null || raw === undefined) warnings.push('No results artifact found; using safe defaults.');
  else if (typeof raw !== 'object' || Array.isArray(raw)) {
    warnings.push('Results artifact is not an object; using safe defaults.');
  }
  if (
    source.schemaVersion !== undefined &&
    source.schemaVersion !== ARTIFACT_SCHEMA_VERSION
  ) {
    warnings.push(
      `Unsupported artifact schema version ${String(source.schemaVersion)}; reading known fields only.`,
    );
  }

  const generatedAt = typeof source.generatedAt === 'string' ? source.generatedAt : null;
  const appVersion = cleanText(source.appVersion, 64);
  const contactRaw = cleanEmail(source.contactEmail);
  if (typeof source.contactEmail === 'string' && source.contactEmail.trim() !== '' && contactRaw === null) {
    warnings.push('Artifact contact email is malformed; omitting it.');
  }

  const criterionById = new Map(WCAG22_AAA_CRITERIA.map((entry) => [entry.id, entry]));
  const statusByCriterion = new Map();
  const evidenceByCriterion = new Map();
  const aaaEntries = Array.isArray(source.wcag22aaa) ? source.wcag22aaa : [];
  if (source.wcag22aaa !== undefined && !Array.isArray(source.wcag22aaa)) {
    warnings.push('Artifact wcag22aaa section is not a list; treating every criterion as unknown.');
  }
  for (const entry of aaaEntries) {
    if (entry === null || typeof entry !== 'object') {
      warnings.push('Skipping a malformed AAA entry (not an object).');
      continue;
    }
    const id = entry.criterion;
    if (!criterionById.has(id)) {
      warnings.push(`Ignoring unknown AAA criterion id ${JSON.stringify(id)}.`);
      continue;
    }
    if (!AAA_STATUSES.includes(entry.status)) {
      warnings.push(`Ignoring malformed status for criterion ${id}; marking it unknown.`);
      continue;
    }
    statusByCriterion.set(id, entry.status);
    evidenceByCriterion.set(id, cleanText(entry.evidence, 500));
  }

  const outcomeById = new Map(WCAG30_OUTCOMES.map((entry) => [entry.id, entry]));
  const readinessByOutcome = new Map();
  const noteByOutcome = new Map();
  const w30Entries = Array.isArray(source.wcag30) ? source.wcag30 : [];
  if (source.wcag30 !== undefined && !Array.isArray(source.wcag30)) {
    warnings.push('Artifact wcag30 section is not a list; treating every outcome as unknown.');
  }
  for (const entry of w30Entries) {
    if (entry === null || typeof entry !== 'object') {
      warnings.push('Skipping a malformed 3.0 entry (not an object).');
      continue;
    }
    const id = entry.outcome;
    if (!outcomeById.has(id)) {
      warnings.push(`Ignoring unknown 3.0 outcome id ${JSON.stringify(id)}.`);
      continue;
    }
    if (!READINESS_LEVELS.includes(entry.readiness)) {
      warnings.push(`Ignoring malformed readiness for outcome ${id}; marking it unknown.`);
      continue;
    }
    readinessByOutcome.set(id, entry.readiness);
    noteByOutcome.set(id, cleanText(entry.note, 500));
  }

  const knownIssues = [];
  if (source.knownIssues !== undefined && !Array.isArray(source.knownIssues)) {
    warnings.push('Artifact knownIssues section is not a list; showing no known issues.');
  }
  for (const entry of Array.isArray(source.knownIssues) ? source.knownIssues : []) {
    const id = cleanText(entry?.id, 80);
    const summary = cleanText(entry?.summary, 1000);
    const group = entry?.group;
    if (!id || !summary || !isNeedGroupId(group)) {
      warnings.push('Skipping a malformed known-issue entry.');
      continue;
    }
    knownIssues.push({ id, summary, group });
  }

  return {
    artifact: {
      schemaVersion: ARTIFACT_SCHEMA_VERSION,
      generatedAt,
      appVersion,
      contactEmail: contactRaw || '',
      wcag22aaa: WCAG22_AAA_CRITERIA.map((criterion) => ({
        criterion: criterion.id,
        status: statusByCriterion.get(criterion.id) || 'unknown',
        evidence: evidenceByCriterion.get(criterion.id) || '',
      })),
      wcag30: WCAG30_OUTCOMES.map((outcome) => ({
        outcome: outcome.id,
        readiness: readinessByOutcome.get(outcome.id) || 'unknown',
        note: noteByOutcome.get(outcome.id) || '',
      })),
      knownIssues,
    },
    warnings,
  };
};

const aggregateAaa = (statuses) => {
  const applicable = statuses.filter((status) => status !== 'not-applicable');
  if (applicable.length === 0) return 'not-applicable';
  if (applicable.some((status) => status === 'unknown')) return 'unknown';
  if (applicable.some((status) => status === 'not-supported')) return 'not-supported';
  if (applicable.some((status) => status === 'partial')) return 'partly-supported';
  return 'supported';
};

const aggregateReadiness = (levels) => {
  const applicable = levels.filter((level) => level !== 'not-applicable');
  if (applicable.length === 0) return 'not-applicable';
  if (applicable.some((level) => level === 'unknown')) return 'unknown';
  if (applicable.some((level) => level === 'partial')) return 'partial';
  return 'supported';
};

/***
 * MARK: groupStatementResults
 * @description Applies the mapping doc's aggregation rule to a parsed
 *   artifact: one entry per need group with its AAA rows, 3.0 rows, and
 *   aggregated group statuses. Pure and total over NEED_GROUPS.
 * @example groupStatementResults(parseResultsArtifact(FALLBACK_ARTIFACT).artifact)[0].group.id => 'seeing'
 ***/
export const groupStatementResults = (parsedArtifact) => {
  const artifact = parsedArtifact && typeof parsedArtifact === 'object' ? parsedArtifact : null;
  const statusByCriterion = new Map(
    (artifact?.wcag22aaa || []).map((row) => [row.criterion, row]),
  );
  const readinessByOutcome = new Map(
    (artifact?.wcag30 || []).map((row) => [row.outcome, row]),
  );
  const issuesByGroup = new Map(NEED_GROUPS.map((group) => [group.id, []]));
  for (const issue of artifact?.knownIssues || []) {
    if (issuesByGroup.has(issue.group)) issuesByGroup.get(issue.group).push(issue);
  }
  return NEED_GROUPS.map((group) => {
    const criteria = WCAG22_AAA_CRITERIA.filter((entry) => entry.group === group.id);
    const aaaRows = criteria.map((criterion) => ({
      ...criterion,
      status: statusByCriterion.get(criterion.id)?.status || 'unknown',
      evidence: statusByCriterion.get(criterion.id)?.evidence || '',
    }));
    const outcomes = WCAG30_OUTCOMES.filter((entry) => entry.group === group.id);
    const w30Rows = outcomes.map((outcome) => ({
      ...outcome,
      readiness: readinessByOutcome.get(outcome.id)?.readiness || 'unknown',
      note: readinessByOutcome.get(outcome.id)?.note || '',
    }));
    const aaaStatus = aggregateAaa(aaaRows.map((row) => row.status));
    const w30Readiness = aggregateReadiness(w30Rows.map((row) => row.readiness));
    return {
      group,
      aaaStatus,
      aaaLabel: GROUP_AAA_LABELS[aaaStatus],
      w30Readiness,
      w30Label: READINESS_LABELS[w30Readiness],
      aaaRows,
      w30Rows,
      knownIssues: issuesByGroup.get(group.id),
    };
  });
};

/***
 * MARK: routing
 * @description Single route table for the KainBain SPA (HashRouter-first).
 * The router location is the source of truth for the current view:
 * leaving a view IS a navigation, so a stale docs/task location can never
 * survive it, and refresh re-opens the CURRENT route with its params.
 *
 * Route table (canonical paths; the HashRouter renders them as `#/...` URLs):
 *
 * | View         | Canonical path        | Legacy entries (redirect)        |
 * |--------------|-----------------------|----------------------------------|
 * | Orchestrator | `/`                   | `#/orchestrator`, `?view=...`    |
 * | Files & Repo | `/explorer`           | `?view=explorer`                 |
 * | Settings     | `/settings`           | `?view=settings`                 |
 * | System Settings| `/system-settings/:section?` | (none)                    |
 * | Observability| `/observability`      | `?view=observability`            |
 * | Docs         | `/docs/:slug?`        | `#docs`, `?view=docs`            |
 * | Task detail  | `/tasks/:id`          | `#/task/:id`, `?task=:id`        |
 * | Task review  | `/tasks/:id/review`   | (existing shape, now canonical)  |
 * | Task survey  | `/tasks/:id/survey`   | `#/task/:id/survey` (legacy)       |
 * | Retrospective| `/retrospective`      | (none — new view, no legacy)     |
 * | Accessibility| `/accessibility`      | `?view=accessibility`            |
 *
 * Note: `/settings` is project-scoped (ProjectSettings); `/system-settings` is
 * application-level (SystemSettingsPage, a full screen — not a modal). The
 * System Menu entry and the `S` shortcut open it in a new window by default
 * (`openSystemSettings`), falling back to same-tab `setView('system-settings')`
 * when the popout is blocked or the viewport is phone-narrow. The `:section`
 * segment (or `?section=`) deep-links a settings tab.
 *
 * Refresh guarantees:
 * - Refresh re-opens the CURRENT route (docs slug, task id preserved).
 * - Unknown locations keep the current view (explicit catch-all, no switch).
 * - Each view entry is one history entry; back/forward traverse real entries.
 * - Legacy-redirect normalisation uses history REPLACE, never a push.
 *
 * How to add a view: add its canonical path here + a `<Route>` in
 * `routes.jsx` + a `viewToPath`/`routeToView` row + redirect/tests below.
 * A future move to `<BrowserRouter>` is mechanical: canonical paths are
 * already full-URL shaped; only the router shell in `main.jsx` changes.
 ***/

export const ROUTES = {
  orchestrator: '/',
  explorer: '/explorer',
  settings: '/settings',
  systemSettings: '/system-settings',
  systemSettingsSection: '/system-settings/:section',
  observability: '/observability',
  docs: '/docs',
  docsArticle: '/docs/:slug',
  taskDetail: '/tasks/:id',
  taskReview: '/tasks/:id/review',
  taskSurvey: '/tasks/:id/survey',
  retrospective: '/retrospective',
  accessibility: '/accessibility',
};

/***
 * MARK: viewToPath
 * @description Canonical router path for a view id. The `setView` facade
 *   navigates here, so every view entry writes exactly one history entry.
 * @param {string} view - View id (`orchestrator`, `explorer`, `settings`,
 *   `system-settings`, `observability`, `docs`, `task-detail`/`task`,
 *   `task-review`, `tasks`, `retrospective`, `accessibility`).
 * @param {Object} [opts]
 * @param {string} [opts.taskId] - Task id for task-detail/task-review paths.
 * @param {string} [opts.slug] - Docs slug for the docs article path.
 * @param {string} [opts.section] - Settings tab id for the system-settings path.
 * @returns {string|null} Canonical path, or null for unknown views.
 * @example viewToPath('docs', { slug: 'architecture' }) => '/docs/architecture'
 ***/
export function viewToPath(view, opts = {}) {
  const { taskId, slug, section } = opts;
  switch (view) {
    case 'orchestrator':
    case 'tasks':
      return '/';
    case 'explorer':
      return '/explorer';
    case 'settings':
      return '/settings';
    case 'system-settings':
      return section ? `/system-settings/${encodeURIComponent(section)}` : '/system-settings';
    case 'observability':
      return '/observability';
    case 'docs':
      return slug ? `/docs/${encodeURIComponent(slug)}` : '/docs';
    case 'task-detail':
    case 'task':
      return taskId ? `/tasks/${encodeURIComponent(taskId)}` : '/';
    case 'task-review':
      return taskId ? `/tasks/${encodeURIComponent(taskId)}/review` : '/';
    case 'task-survey':
      return taskId ? `/tasks/${encodeURIComponent(taskId)}/survey` : '/';
    case 'retrospective':
      return '/retrospective';
    case 'accessibility':
      return '/accessibility';
    default:
      return null;
  }
}

/***
 * MARK: routeToView
 * @description Resolves a router pathname to its view + params.
 *   Returns null for unknown paths so the caller keeps the current view
 *   instead of switching on fragments like `/main-content`.
 * @param {string} pathname - Router pathname (e.g. `/docs/architecture`).
 * @returns {{ view: string, taskId?: string, slug?: string, section?: string }|null}
 * @example routeToView('/tasks/t1/review') => { view: 'task-review', taskId: 't1' }
 * @example routeToView('/system-settings/models') => { view: 'system-settings', section: 'models' }
 ***/
export function routeToView(pathname) {
  if (typeof pathname !== 'string') return null;
  const path = pathname.length > 1 ? pathname.replace(/\/+$/, '') : pathname;
  if (path === '/' || path === '/orchestrator') return { view: 'orchestrator' };
  if (path === '/explorer') return { view: 'explorer' };
  if (path === '/settings') return { view: 'settings' };
  if (path === '/system-settings') return { view: 'system-settings' };
  const systemSettingsMatch = path.match(/^\/system-settings\/([^/]+)$/);
  if (systemSettingsMatch) {
    return { view: 'system-settings', section: safeDecode(systemSettingsMatch[1]) };
  }
  if (path === '/observability') return { view: 'observability' };
  if (path === '/retrospective') return { view: 'retrospective' };
  if (path === '/accessibility') return { view: 'accessibility' };
  if (path === '/docs') return { view: 'docs' };
  const docsMatch = path.match(/^\/docs\/([^/]+)$/);
  if (docsMatch) return { view: 'docs', slug: safeDecode(docsMatch[1]) };
  const reviewMatch = path.match(/^\/(?:tasks|task)\/([^/]+)\/review$/);
  if (reviewMatch) return { view: 'task-review', taskId: safeDecode(reviewMatch[1]) };
  const surveyMatch = path.match(/^\/(?:tasks|task)\/([^/]+)\/survey$/);
  if (surveyMatch) return { view: 'task-survey', taskId: safeDecode(surveyMatch[1]) };
  // Legacy singular shape (`#/task/:id`) — canonicalises to `/tasks/:id`.
  const detailMatch = path.match(/^\/(?:tasks|task)\/([^/]+)$/);
  if (detailMatch) return { view: 'task-detail', taskId: safeDecode(detailMatch[1]) };
  return null;
}

function safeDecode(segment) {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
}

const LEGACY_VIEW_PATHS = {
  orchestrator: '/',
  tasks: '/',
  explorer: '/explorer',
  settings: '/settings',
  'system-settings': '/system-settings',
  observability: '/observability',
  docs: '/docs',
  accessibility: '/accessibility',
};

/***
 * MARK: normalizeLegacyUrl
 * @description Maps legacy entry URLs onto their canonical hash ONCE at boot
 *   (via `history.replaceState`, so no extra history entry is created).
 *   Returns null when the URL is already canonical and must be left alone.
 * @param {{ hash?: string, search?: string, pathname?: string }} loc
 *   A `window.location`-like. Defaults to the live location.
 * @returns {string|null} Canonical hash (e.g. `#/docs/architecture`) or null.
 * @example normalizeLegacyUrl({ hash: '#docs', search: '', pathname: '/' }) => '#/docs'
 ***/
export function normalizeLegacyUrl(loc = defaultLocation()) {
  const hash = loc?.hash || '';
  const search = loc?.search || '';
  const pathname = loc?.pathname || '';

  // Legacy query entries (`?view=`, `?task=`) win, matching the old boot order.
  if (search) {
    try {
      const params = new URLSearchParams(search);
      const queryView = params.get('view');
      const queryTask = params.get('task');
      const wantsReview = queryView === 'task-review' || hash.includes('/review');
      const wantsSurvey = queryView === 'task-survey' || hash.includes('/survey');
      if (queryTask && (queryView === 'task-review' || queryView === 'task-survey' || !queryView)) {
        if (wantsSurvey) return `#/tasks/${encodeURIComponent(queryTask)}/survey`;
        return wantsReview
          ? `#/tasks/${encodeURIComponent(queryTask)}/review`
          : `#/tasks/${encodeURIComponent(queryTask)}`;
      }
      if (queryView && LEGACY_VIEW_PATHS[queryView] !== undefined) {
        if ((queryView === 'task' || queryView === 'task-review') && queryTask) {
          return queryView === 'task-review'
            ? `#/tasks/${encodeURIComponent(queryTask)}/review`
            : `#/tasks/${encodeURIComponent(queryTask)}`;
        }
        if (queryView === 'task' || queryView === 'task-review' || queryView === 'tasks') {
          return '#/';
        }
        return `#${LEGACY_VIEW_PATHS[queryView] === '/' ? '/' : LEGACY_VIEW_PATHS[queryView]}`;
      }
    } catch {
      // fall through to hash/path handling
    }
  }

  if (hash === '#docs') return '#/docs';
  if (hash === '#/orchestrator') return '#/';
  const singularTask = hash.match(/^#\/task\/([^?#/]+)(\/review|\/survey)?\/?$/);
  if (singularTask) {
    const id = singularTask[1];
    if (singularTask[2] === '/review') return `#/tasks/${id}/review`;
    if (singularTask[2] === '/survey') return `#/tasks/${id}/survey`;
    return `#/tasks/${id}`;
  }
  // A present hash is either already canonical (`#/...`) or an in-page
  // fragment (`#main-content`): both must be left alone.
  if (hash) return null;

  // Server-style paths (no hash yet): only mapped when they name a real view.
  if (!pathname || pathname === '/') return null;
  const asRoute = routeToView(pathname);
  if (asRoute) {
    if (asRoute.view === 'orchestrator') return '#/';
    if (asRoute.view === 'docs') return asRoute.slug ? `#/docs/${asRoute.slug}` : '#/docs';
    if (asRoute.view === 'task-detail') return `#/tasks/${asRoute.taskId}`;
    if (asRoute.view === 'task-review') return `#/tasks/${asRoute.taskId}/review`;
    if (asRoute.view === 'task-survey') return `#/tasks/${asRoute.taskId}/survey`;
    if (asRoute.view === 'system-settings') {
      return `#${viewToPath('system-settings', { section: asRoute.section })}`;
    }
    return `#${viewToPath(asRoute.view)}`;
  }
  return null;
}

function defaultLocation() {
  if (typeof window !== 'undefined' && window.location) return window.location;
  return { hash: '', search: '', pathname: '/' };
}

