          <div className="h-6 w-px bg-border-standard mx-1 hidden xl:block" aria-hidden="true" />

          {/* Project Selector (Pill format per mockup with Hide/Show Archived #29) */}
          <div className="relative" ref={projectMenuRef}>
            <button
